SELECT UPPER('Stefan'), LOWER('LOWER'), INITCAP('ioana MARIA') FROM DUAL;
-- STEFAN, lower, Ioana Maria

SELECT SUBSTR('ABCDEFG', 3, 4), SUBSTR('ABCDEFG', -3, 2) FROM DUAL;
-- CDEF, EF

SELECT INSTR('CORPORATE FLOOR', 'OR', 3, 2) FROM DUAL;
-- 14

SELECT '-' || TRIM('   test   ') || '-' FROM DUAL;
-- -test-

SELECT COUNT(*) FROM studenti WHERE LOWER(prenume) = 'ioana';
-- 3  (fără LOWER, cu 'ioana', ar fi 0)

